前言 最近在 GitHub 学生包里发现了一个好东西——GitHub Copilot CLI&hellip;
Copilot CLI 听说这个产品是 Claude Code 的竞品，刚看新闻说微软让员工从Claude Code转用它
正好对比体验一下
大一 C 语言实践作业 翻到之前大一的 C 语言作业——学生管理系统&hellip;
当时懵懂无知，完全不懂什么是 agent&hellip;
用 DeepSeek 改了又改，虽然（but still）仍然不会古法编程&hellip;
现在用 Copilot CLI，几分钟就能写好，完全不用手。
搭一个网页版吧 核心代码 from flask import Flask, g, render_template, request, redirect, url_for import sqlite3 import os BASE_DIR = os.path.dirname(__file__) DB_PATH = os.path.join(BASE_DIR, &#39;student.db&#39;) app = Flask(__name__, instance_path=BASE_DIR) def get_db(): db = getattr(g, &#39;_database&#39;, None) if db is None: db = g._database = sqlite3.connect(DB_PATH) db.row_factory = sqlite3.Row return db def init_db(): db = get_db() cur = db.cursor() cur.execute(&#39;&#39;&#39; CREATE TABLE IF NOT EXISTS students ( id TEXT PRIMARY KEY, name TEXT, gender TEXT, birth TEXT, address TEXT, phone TEXT, email TEXT ) &#39;&#39;&#39;) cur.execute(&#39;&#39;&#39; CREATE TABLE IF NOT EXISTS courses ( id INTEGER PRIMARY KEY AUTOINCREMENT, sid TEXT, cid TEXT, name TEXT, credit REAL ) &#39;&#39;&#39;) cur.execute(&#39;&#39;&#39; CREATE TABLE IF NOT EXISTS scores ( id INTEGER PRIMARY KEY AUTOINCREMENT, ssid TEXT, sname TEXT, scid TEXT, cname TEXT, score REAL ) &#39;&#39;&#39;) db.commit() @app.teardown_appcontext def close_connection(exception): db = getattr(g, &#39;_database&#39;, None) if db is not None: db.close() with app.app_context(): init_db() @app.route(&#39;/&#39;) def index(): return render_template(&#39;index.html&#39;) # Students @app.route(&#39;/students&#39;) def students(): db = get_db() cur = db.execute(&#39;SELECT * FROM students ORDER BY id&#39;) rows = cur.fetchall() return render_template(&#39;students.html&#39;, students=rows) @app.route(&#39;/students/add&#39;, methods=[&#39;GET&#39;, &#39;POST&#39;]) def add_student(): if request.method == &#39;POST&#39;: form = request.form db = get_db() try: db.execute(&#39;INSERT INTO students(id,name,gender,birth,address,phone,email) VALUES (?,?,?,?,?,?,?)&#39;, (form[&#39;id&#39;], form[&#39;name&#39;], form.get(&#39;gender&#39;,&#39;&#39;), form.get(&#39;birth&#39;,&#39;&#39;), form.get(&#39;address&#39;,&#39;&#39;), form.get(&#39;phone&#39;,&#39;&#39;), form.get(&#39;email&#39;,&#39;&#39;))) db.commit() except sqlite3.IntegrityError: return &#39;学号已存在&#39;, 400 return redirect(url_for(&#39;students&#39;)) return render_template(&#39;student_form.html&#39;, student=None) @app.route(&#39;/students/edit/&lt;sid&gt;&#39;, methods=[&#39;GET&#39;,&#39;POST&#39;]) def edit_student(sid): db = get_db() if request.method == &#39;POST&#39;: form = request.form db.execute(&#39;UPDATE students SET id=?,name=?,gender=?,birth=?,address=?,phone=?,email=? WHERE id=?&#39;, (form[&#39;id&#39;], form[&#39;name&#39;], form.get(&#39;gender&#39;,&#39;&#39;), form.get(&#39;birth&#39;,&#39;&#39;), form.get(&#39;address&#39;,&#39;&#39;), form.get(&#39;phone&#39;,&#39;&#39;), form.get(&#39;email&#39;,&#39;&#39;), sid)) db.commit() return redirect(url_for(&#39;students&#39;)) cur = db.execute(&#39;SELECT * FROM students WHERE id=?&#39;, (sid,)) student = cur.fetchone() return render_template(&#39;student_form.html&#39;, student=student) @app.route(&#39;/students/delete/&lt;sid&gt;&#39;, methods=[&#39;POST&#39;]) def delete_student(sid): db = get_db() db.execute(&#39;DELETE FROM students WHERE id=?&#39;, (sid,)) db.execute(&#39;DELETE FROM courses WHERE sid=?&#39;, (sid,)) db.execute(&#39;DELETE FROM scores WHERE ssid=?&#39;, (sid,)) db.commit() return redirect(url_for(&#39;students&#39;)) # Courses @app.route(&#39;/courses&#39;) def courses(): db = get_db() cur = db.execute(&#39;SELECT * FROM courses ORDER BY sid, cid&#39;) rows = cur.fetchall() return render_template(&#39;courses.html&#39;, courses=rows) @app.route(&#39;/courses/add&#39;, methods=[&#39;GET&#39;,&#39;POST&#39;]) def add_course(): if request.method == &#39;POST&#39;: f = request.form db = get_db() db.execute(&#39;INSERT INTO courses(sid,cid,name,credit) VALUES (?,?,?,?)&#39;, (f[&#39;sid&#39;], f[&#39;cid&#39;], f[&#39;name&#39;], float(f.get(&#39;credit&#39;,0)))) db.commit() return redirect(url_for(&#39;courses&#39;)) return render_template(&#39;course_form.html&#39;, course=None) @app.route(&#39;/courses/delete/&lt;int:id&gt;&#39;, methods=[&#39;POST&#39;]) def delete_course(id): db = get_db() # delete related scores cur = db.execute(&#39;SELECT sid,cid,name FROM courses WHERE id=?&#39;, (id,)) row = cur.fetchone() if row: db.execute(&#39;DELETE FROM scores WHERE scid=? AND ssid=?&#39;, (row[&#39;cid&#39;], row[&#39;sid&#39;])) db.execute(&#39;DELETE FROM courses WHERE id=?&#39;, (id,)) db.commit() return redirect(url_for(&#39;courses&#39;)) # Scores @app.route(&#39;/scores&#39;) def scores(): db = get_db() cur = db.execute(&#39;SELECT * FROM scores ORDER BY ssid&#39;) rows = cur.fetchall() return render_template(&#39;scores.html&#39;, scores=rows) @app.route(&#39;/scores/add&#39;, methods=[&#39;GET&#39;,&#39;POST&#39;]) def add_score(): if request.method == &#39;POST&#39;: f = request.form db = get_db() db.execute(&#39;INSERT INTO scores(ssid,sname,scid,cname,score) VALUES (?,?,?,?,?)&#39;, (f[&#39;ssid&#39;], f[&#39;sname&#39;], f[&#39;scid&#39;], f[&#39;cname&#39;], float(f.get(&#39;score&#39;,0)))) db.commit() return redirect(url_for(&#39;scores&#39;)) return render_template(&#39;score_form.html&#39;, score=None) @app.route(&#39;/scores/delete/&lt;int:id&gt;&#39;, methods=[&#39;POST&#39;]) def delete_score(id): db = get_db() db.execute(&#39;DELETE FROM scores WHERE id=?&#39;, (id,)) db.commit() return redirect(url_for(&#39;scores&#39;)) # Stats @app.route(&#39;/stats&#39;) def stats(): sid = request.args.get(&#39;sid&#39;) db = get_db() if not sid: return render_template(&#39;stats.html&#39;, sid=None, stats=None) # calculate avg, total credits passed cur = db.execute(&#39;SELECT score, scid FROM scores WHERE ssid=?&#39;, (sid,)) rows = cur.fetchall() if not rows: return render_template(&#39;stats.html&#39;, sid=sid, stats=None) total = 0.0 cnt = 0 credits = 0.0 for r in rows: total += r[&#39;score&#39;] cnt += 1 if r[&#39;score&#39;] &gt;= 60: c = db.execute(&#39;SELECT credit FROM courses WHERE sid=? AND cid=?&#39;, (sid, r[&#39;scid&#39;])).fetchone() if c: credits += c[&#39;credit&#39;] avg = total / cnt if cnt else 0 return render_template(&#39;stats.html&#39;, sid=sid, stats={&#39;avg&#39;:avg,&#39;credits&#39;:credits,&#39;count&#39;:cnt}) # Course ranking @app.route(&#39;/rank/&lt;cid&gt;&#39;) def rank(cid): db = get_db() cur = db.execute(&#39;SELECT sname, score FROM scores WHERE scid=? ORDER BY score DESC&#39;, (cid,)) rows = cur.fetchall() return render_template(&#39;rank.html&#39;, cid=cid, rows=rows) if __name__ == &#39;__main__&#39;: app.run(host=&#39;127.0.0.1&#39;, port=5000, debug=True) 是用flask搭的 代码不详说，就是一个非常简单的项目，.db文件是数据库，用的sqlite，打开试试，在5000端口跑起来 优雅且流畅，不禁感慨AI可以取代多少之前人工的工作，从有这个想法到落地实现这个项目仅用了20分钟不到。。。 但是在想想，以后最重要的可能就是那个想法。。。
Claude Code 最近通过Vidar的老学长搞到了ClaudeCode的key，每天有一些额度，正好让我这个穷人体验一下。
感受 目前的感受是快，比那个垃圾的Copilot不知道准确了多少，降低了不少重复工作
本人还在使用中，等我之后的文章详细说说，以后他就是主力了
